output_text:
[
  {
    "id": "use_entry_cart",
    "text": "A shopper is obliged to take the cart from the entry cart station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": "at(1,5)",
        "cart_available_at_entry": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "pickup_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_station",
              "cartAt(1,5)",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entry_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they are currently pushing the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_shelf_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "take_shelf_item",
          {
            "not": "pushing_cart"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying groceries by hand instead of putting them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "cart_not_in_use": {
          "not": "hasCart"
        }
      },
      "events": {
        "hand_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cart_not_in_use"
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "hand_item_pickup"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_northwest_bay",
    "text": "After taking a cart, the shopper is obliged to leave it at the northwest cart-return bay before exiting.",
    "abstraction": {
      "state_properties": {
        "northwest_cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "northwest_cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "exit_without_cart",
    "text": "A shopper is prohibited from leaving the supermarket while still possessing the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "at_exit": "at(9,5)"
      },
      "events": {
        "exit_store": {
          "pre": {
            "and": [
              "at_exit",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          "pushing_cart"
        ]
      }
    }
  },
  {
    "id": "leave_cart_only_in_bay",
    "text": "A shopper is prohibited from leaving the cart anywhere other than the designated cart-return bay at the northwest corner.",
    "abstraction": {
      "state_properties": {
        "designated_cart_return_bay": "at(0,1)"
      },
      "events": {
        "drop_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "drop_cart",
          {
            "not": "designated_cart_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "cart_west_wall_no_east",
    "text": "While pushing a cart on the west-wall return corridor, the shopper is prohibited from turning east into the store aisles.",
    "abstraction": {
      "state_properties": {
        "west_wall_return_corridor": {
          "or": [
            "at(0,1)",
            "at(0,2)",
            "at(0,3)",
            "at(0,4)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "east_turn_from_west_wall_with_cart": {
          "pre": {
            "and": [
              "west_wall_return_corridor",
              "pushing_cart",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "east_turn_from_west_wall_with_cart"
    }
  },
  {
    "id": "cart_no_south_from_middle_aisle",
    "text": "While pushing a cart at the middle shelf-access cell, the shopper is prohibited from moving south toward the exit corridor.",
    "abstraction": {
      "state_properties": {
        "middle_shelf_access_cell": "at(2,4)",
        "pushing_cart": "hasCart",
        "cart_already_parked": "cartAt(0,1)"
      },
      "events": {
        "south_from_middle_with_cart": {
          "pre": {
            "and": [
              "middle_shelf_access_cell",
              "pushing_cart",
              "S"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "south_from_middle_with_cart"
    }
  }
]
